INSERT INTO item VALUES (374,'Animal Friendship','Ring',NULL,'No','Faint enchantment','3','10,800 gp',NULL,'Forge Ring, charm animal',NULL,NULL,'\n      <div topic=\"Animal Friendship\" level=\"8\"><p><b>Animal Friendship:</b> On command, this ring affects an animal as if the wearer had cast <i>charm animal</i>.</p><p>Faint enchantment; CL 3rd; Forge Ring, <i>charm animal</i>; Price 10,800 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (375,'Blinking','Ring',NULL,'No','Moderate transmutation','7','27,000 gp',NULL,'Forge Ring, blink',NULL,NULL,'\n      <div topic=\"Blinking\" level=\"8\"><p><b>Blinking:</b> On command, this ring makes the wearer blink, as with the <i>blink</i> spell.</p><p>Moderate transmutation; CL 7th; Forge Ring, <i>blink</i>; Price 27,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (376,'Chameleon Power','Ring',NULL,'No','Faint illusion','3','12,700 gp',NULL,'Forge Ring, disguise self, invisibility',NULL,NULL,'\n      <div topic=\"Chameleon Power\" level=\"8\"><p><b>Chameleon Power:</b> As a free action, the wearer of this ring can gain the ability to magically blend in with the surroundings. This provides a +10 competence bonus on her Hide checks. As a standard action, she can also command the ring to utilize the spell <i>disguise self</i> as often as she wants.</p><p>Faint illusion; CL 3rd; Forge Ring, <i>disguise self</i>,  <i>invisibility</i>; Price 12,700 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (377,'Climbing','Ring',NULL,'No','Faint transmutatation','5','2,500 gp',NULL,'Forge Ring, creator must have 5 ranks in the Climb skill',NULL,NULL,'\n      <div topic=\"Climbing\" level=\"8\"><p><b>Climbing:</b> This ring is actually a magic leather cord that ties around a finger. It continually grants the wearer a +5 competence bonus on Climb checks.</p><p>Faint transmutatation; CL 5th; Forge Ring, creator must have 5 ranks in the Climb skill; Price 2,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (378,'Climbing, Improved','Ring',NULL,'No','Faint transmutation','5','10,000 gp',NULL,'Forge Ring, creator must have 10 ranks in the Climb skill',NULL,NULL,'\n      <div topic=\"Climbing, Improved\" level=\"8\"><p><b>Climbing, Improved:</b> As climbing, except it grants a +10 competence bonus on its wearer\'s Climb checks.</p><p>Faint transmutation; CL 5th; Forge Ring, creator must have 10 ranks in the Climb skill; Price 10,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (379,'Counterspells','Ring',NULL,'No','Moderate evocation','11','4,000 gp',NULL,'Forge Ring, imbue with spell ability',NULL,NULL,'\n      <div topic=\"Counterspells\" level=\"8\"><p><b>Counterspells:</b> This ring might seem to be a <i>ring of spell storing</i> upon first examination. However, while it allows a single spell of 1st through 6th level to be cast into it, that spell cannot be cast out of the ring again. Instead, should that spell ever be cast upon the wearer, the spell is immediately countered, as a counterspell action, requiring no action (or even knowledge) on the wearer\'s part. Once so used, the spell cast within the ring is gone. A new spell (or the same one as before) may be placed in it again.</p><p>Moderate evocation; CL 11th; Forge Ring, <i>imbue with spell ability</i>; Price 4,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (380,'Djinni Calling','Ring',NULL,'No','Strong conjuration','17','125,000 gp',NULL,'Forge Ring, gate',NULL,NULL,'\n      <div topic=\"Djinni Calling\" level=\"8\"><p><b>Djinni Calling:</b> One of the many rings of fable, this \'genie\' ring is most useful indeed. It serves as a special <i>gate</i> by means of which a specific djinni can be called from the Elemental Plane of Air. When the ring is rubbed (a standard action), the call goes out, and the djinni appears on the next round. The djinni faithfully obeys and serves the wearer of the ring, but never for more than 1 hour per day. If the djinni of the ring is ever killed, the ring becomes nonmagical and worthless.</p><p>Strong conjuration; CL 17th; Forge Ring, <i>gate</i>; Price 125,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (381,'Ring of Elemental Command (Water)','Ring',NULL,'No','Strong conjuration','15','200,000 gp',NULL,'Forge Ring, summon monster VI, all appropriate spells',NULL,NULL,'\n      <div topic=\"Ring of Elemental Command\" level=\"8\"><p><i>Ring of Elemental Command (Water)</i></p><ul>\n <li> <i>Water walk</i> (unlimited use)</li>\n <li> <i>Create water</i> (unlimited use)</li>\n <li> <i>Water breathing</i> (unlimited use)</li>\n <li> <i>Wall of ice</i> (once per day)</li>\n <li> <i>Ice storm</i> (twice per week)</li>\n <li> <i>Control</i> water (twice per week)</li>\n</ul><p>The ring appears to be a <i>ring of water walking</i> until the established condition is met.</p><p>Strong conjuration; CL 15th; Forge Ring, <i>summon monster VI</i>, all appropriate spells; Price 200,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (382,'Energy Resistance, Minor','Ring',NULL,'No','Faint (minor or major) or moderate (greater) abjuration','3','12,000 gp',NULL,'Forge Ring, resist energy',NULL,NULL,'\n      <div topic=\"Energy Resistance\" level=\"8\"><p><b>Energy Resistance:</b> This reddish iron ring continually protects the wearer from damage from one type of energy-acid, cold, electricity, fire, or sonic (chosen by the creator of the item; determine randomly if found as part of a treasure hoard). Each time the wearer would normally take such damage, subtract the ring\'s resistance value from the damage dealt.</p><p>A <i>minor ring of energy resistance</i> grants 10 points of resistance. A <i>major ring of energy resistance</i> grants 20 points of resistance. A <i>greater ring of energy resistance</i> grants 30 points of resistance.</p><p>Faint (minor or major) or moderate (greater) abjuration; CL 3rd  (minor), 7th (major), or 11th (greater); Forge Ring, <i>resist energy</i>; Price 12,000 gp (minor), 28,000 gp (major), 44,000 gp (greater).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (383,'Energy Resistance, Major','Ring',NULL,'No','Faint (minor or major) or moderate (greater) abjuration','3','28,000 gp',NULL,'Forge Ring, resist energy',NULL,NULL,'\n      <div topic=\"Energy Resistance\" level=\"8\"><p><b>Energy Resistance:</b> This reddish iron ring continually protects the wearer from damage from one type of energy-acid, cold, electricity, fire, or sonic (chosen by the creator of the item; determine randomly if found as part of a treasure hoard). Each time the wearer would normally take such damage, subtract the ring\'s resistance value from the damage dealt.</p><p>A <i>minor ring of energy resistance</i> grants 10 points of resistance. A <i>major ring of energy resistance</i> grants 20 points of resistance. A <i>greater ring of energy resistance</i> grants 30 points of resistance.</p><p>Faint (minor or major) or moderate (greater) abjuration; CL 3rd  (minor), 7th (major), or 11th (greater); Forge Ring, <i>resist energy</i>; Price 12,000 gp (minor), 28,000 gp (major), 44,000 gp (greater).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (384,'Energy Resistance, Greater','Ring',NULL,'No','Faint (minor or major) or moderate (greater) abjuration','3','44,000 gp',NULL,'Forge Ring, resist energy',NULL,NULL,'\n      <div topic=\"Energy Resistance\" level=\"8\"><p><b>Energy Resistance:</b> This reddish iron ring continually protects the wearer from damage from one type of energy-acid, cold, electricity, fire, or sonic (chosen by the creator of the item; determine randomly if found as part of a treasure hoard). Each time the wearer would normally take such damage, subtract the ring\'s resistance value from the damage dealt.</p><p>A <i>minor ring of energy resistance</i> grants 10 points of resistance. A <i>major ring of energy resistance</i> grants 20 points of resistance. A <i>greater ring of energy resistance</i> grants 30 points of resistance.</p><p>Faint (minor or major) or moderate (greater) abjuration; CL 3rd  (minor), 7th (major), or 11th (greater); Forge Ring, <i>resist energy</i>; Price 12,000 gp (minor), 28,000 gp (major), 44,000 gp (greater).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (385,'Evasion','Ring',NULL,'No','Moderate transmutation','7','25,000 gp',NULL,'Forge Ring, jump',NULL,NULL,'\n      <div topic=\"Evasion\" level=\"8\"><p><b>Evasion:</b> This ring continually grants the wearer the ability to avoid damage as if she had evasion. Whenever she makes a Reflex saving throw to determine whether she takes half damage, a successful save results in no damage.</p><p>Moderate transmutation; CL 7th; Forge Ring, <i>jump</i>; Price 25,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (386,'Feather Falling','Ring',NULL,'No','Faint transmutation','1','2,200 gp',NULL,'Forge Ring, feather fall',NULL,NULL,'\n      <div topic=\"Feather Falling\" level=\"8\"><p><b>Feather Falling:</b> This ring is crafted with a feather pattern all around its edge. It acts exactly like a <i>Feather fall</i> spell, activated immediately if the wearer falls more than 5 feet.</p><p>Faint transmutation; CL 1st; Forge Ring, <i>feather fall</i>; Price 2,200 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (387,'Force Shield','Ring',NULL,'No','Moderate evocation','9','8,500 gp',NULL,'Forge Ring, wall of force',NULL,NULL,'\n      <div topic=\"Force Shield\" level=\"8\"><p><b>Force Shield:</b> An iron band, this simple ring generates a shield-sized (and shield-shaped) <i>wall of force</i> that stays with the ring and can be wielded by the wearer as if it were a heavy shield (+2 AC). This special creation has no armor check penalty or arcane spell failure chance since it is weightless and encumbrance-free. It can be activated and deactivated at will as a free action.</p><p>Moderate evocation; CL 9th; Forge Ring, <i>wall of force</i>; Price 8,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (388,'Freedom of Movement','Ring',NULL,'No','Moderate abjuration','7','40,000 gp',NULL,'Forge Ring, freedom of movement',NULL,NULL,'\n      <div topic=\"Freedom of Movement\" level=\"8\"><p><b>Freedom of Movement:</b> This gold ring allows the wearer to act as if continually under the effect of a <i>freedom of movement</i> spell.</p><p>Moderate abjuration; CL 7th; Forge Ring, <i>freedom of movement</i>; Price 40,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (389,'Friend Shield','Ring',NULL,'No','Moderate abjuration','10','50,000 gp (for a pair)',NULL,'Forge Ring, shield other',NULL,NULL,'\n      <div topic=\"Friend Shield\" level=\"8\"><p><b>Friend Shield:</b> These curious rings always come in pairs. A <i>friend shield</i> ring without its mate is useless. Either wearer of one of a pair of the rings can, at any time, command his or her ring to cast a <i>shield other</i> spell with the wearer of the mated ring as the recipient. This effect has no range limitation.</p><p>Moderate abjuration; CL 10th; Forge Ring, <i>shield other</i>; Price 50,000 gp (for a pair).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (390,'Invisibility','Ring',NULL,'No','Faint illusion','3','20,000 gp',NULL,'Forge Ring, invisibility',NULL,NULL,'\n      <div topic=\"Invisibility\" level=\"8\"><p><b>Invisibility:</b> By activating this simple silver ring, the wearer can benefit from <i>invisibility</i>, as the spell.</p><p>Faint illusion; CL 3rd; Forge Ring, <i>invisibility</i>; Price 20,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (391,'Jumping','Ring',NULL,'No','Faint transmutation','2','2,500 gp',NULL,'Forge Ring, creator must have 5 ranks in the Jump skill',NULL,NULL,'\n      <div topic=\"Jumping\" level=\"8\"><p><b>Jumping:</b> This ring continually allows the wearer to leap about, providing a +5 competence bonus on all his Jump checks.</p><p>Faint transmutation; CL 2nd; Forge Ring, creator must have 5 ranks in the Jump skill; Price 2,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (392,'Jumping, Improved','Ring',NULL,'No','Moderate transmutation','7','10,000 gp',NULL,'Forge Ring, creator must have 10 ranks in the Jump skill',NULL,NULL,'\n      <div topic=\"Jumping, Improved\" level=\"8\"><p><b>Jumping, Improved:</b> As jumping, except it grants a +10 competence bonus on its wearer\'s Jump check.</p><p>Moderate transmutation; CL 7th; Forge Ring, creator must have 10 ranks in the Jump skill; Price 10,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (393,'Mind Shielding','Ring',NULL,'No','Faint aburation','3','8,000 gp',NULL,'Forge Ring, nondetection',NULL,NULL,'\n      <div topic=\"Mind Shielding\" level=\"8\"><p><b>Mind Shielding:</b> This ring is usually of fine workmanship and wrought from heavy gold. The wearer is continually immune to <i>detect thoughts</i>,  <i>discern lies</i>,  and any attempt to magically discern her alignment.</p><p>Faint aburation; CL 3rd; Forge Ring, <i>nondetection</i>; Price 8,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (394,'Protection, Ring +1','Ring',NULL,'No','Faint abjuration','5','2,000 gp',NULL,'Forge Ring, shield of faith, caster must be of a level at least three times greater than the bonus of the ring',NULL,NULL,'\n      <div topic=\"Protection\" level=\"8\"><p><b>Protection:</b> This ring offers continual magical protection in the form of a deflection bonus of +1 to +5 to AC.</p><p>Faint abjuration; CL 5th; Forge Ring, <i>shield of faith</i>,  caster must be of a level at least three times greater than the bonus of the ring; Price 2,000 gp (<i>ring +1</i>), 8,000 gp (<i>ring +2</i>), 18,000 gp (<i>ring +3</i>), 32,000 gp (<i>ring +4</i>), 50,000 gp (<i>ring +5</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (395,'Protection, Ring +2','Ring',NULL,'No','Faint abjuration','5','8,000 gp',NULL,'Forge Ring, shield of faith, caster must be of a level at least three times greater than the bonus of the ring',NULL,NULL,'\n      <div topic=\"Protection\" level=\"8\"><p><b>Protection:</b> This ring offers continual magical protection in the form of a deflection bonus of +1 to +5 to AC.</p><p>Faint abjuration; CL 5th; Forge Ring, <i>shield of faith</i>,  caster must be of a level at least three times greater than the bonus of the ring; Price 2,000 gp (<i>ring +1</i>), 8,000 gp (<i>ring +2</i>), 18,000 gp (<i>ring +3</i>), 32,000 gp (<i>ring +4</i>), 50,000 gp (<i>ring +5</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
